import { defineConfig } from "vite";
import { resolve, join, relative } from "node:path";
import { readdirSync, statSync } from "node:fs";

// Pages are generated by scripts/gen.mjs into pages/; the office visualization lives in ../pixel-web.
const PAGES = resolve(__dirname, "pages");
const htmlInputs = (dir, out = {}) => {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) htmlInputs(p, out);
    else if (f.endsWith(".html")) out[relative(PAGES, p).replace(/\.html$/, "").replace(/[\\/]/g, "_")] = p;
  }
  return out;
};

export default defineConfig({
  root: PAGES,
  publicDir: resolve(__dirname, "public"),
  envDir: __dirname,
  resolve: { alias: { "@office": resolve(__dirname, "../pixel-web/src/office/index.js") }, dedupe: ["three"] },
  server: { fs: { allow: [resolve(__dirname, "..")] } },
  build: { outDir: resolve(__dirname, "dist"), emptyOutDir: true, rollupOptions: { input: htmlInputs(PAGES) } },
});
